package com.example.comments;

public final class CommentRenderer {
    private CommentRenderer() {
    }

    /** Render one guestbook comment as an HTML fragment. */
    public static String render(String author, String body) {
        StringBuilder html = new StringBuilder();
        html.append("<p class=\"comment\"><b>").append(author).append("</b> ");
        html.append(body).append("</p>");
        return html.toString();
    }
}

package com.example.comments;

import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class CommentRendererTest {
    @Test
    void wrapsComment() {
        assertTrue(CommentRenderer.render("ann", "hi").startsWith("<p class=\"comment\">"));
    }
}
